tabuleiro = [
    ["O", ".", "X"],
    [".", "X", "."],
    [".", "O", "."],
]

lin = int(input("Linha (1 a 3): "))
col = int(input("Coluna (1 a 3): "))
i = lin - 1
j = col - 1

if tabuleiro[i][j] == ".":
    tabuleiro[i][j] = "X"
else:
    print("Essa casa já está ocupada.")

livres = 0
for linha in tabuleiro:
    print(" ".join(linha))
    for casa in linha:
        if casa == ".":
            livres += 1
print("Casas livres:", livres)
